# Build helpers for Maison de la Verrière

def header(active=""):
    nav = [
        ("MAISON", "page-1.html"),
        ("LA CARTE", "page-2.html"),
        ("LE CELLIER", "page-3.html"),
        ("HISTOIRE", "page-4.html"),
        ("BANQUETS", "page-5.html"),
        ("RÉSERVATIONS", "page-6.html"),
    ]
    nav_html = "".join(
        f'<a class="{"current" if active == href else ""}" href="{href}">{label}</a>'
        for label, href in nav
    )
    return f"""
<header class="site-header">
  <div class="topbar">FONDÉ RUE DES LOMBARDS · MCMLXXXII</div>
  <div class="logo">
    <h1>
      <span class="logo-line-1">MAISON DE LA</span>
      <span class="logo-line-2">VERRIÈRE</span>
    </h1>
    <div class="tagline">Refectory &amp; Cellars</div>
  </div>
  <nav class="site-nav">{nav_html}</nav>
</header>
"""


