def footer():
    return f"""
<footer class="site-footer">
  <div class="footer-cols">
    <div class="footer-col">
      <h4>L'ADRESSE</h4>
      <p>14 Rue des Lombards</p>
      <p>75004 Paris</p>
      <p class="small">Métro Châtelet · Hôtel-de-Ville</p>
    </div>
    <div class="footer-col">
      <h4>LES HEURES</h4>
      <p>Mardi — Samedi</p>
      <p>19h00 — 22h30</p>
      <p class="small">Closed Sun · Mon · 1–15 August</p>
    </div>
    <div class="footer-col">
      <h4>CORRESPONDANCE</h4>
      <p>+33 1 42 78 14 09</p>
      <p>reservations@maisonverriere.fr</p>
      <p class="small">Henri Beauvilliers, maître d'hôtel</p>
    </div>
    <div class="footer-col">
      <h4>PLAN DE LA MAISON</h4>
      <ul>
        <li>Maison</li>
        <li>La Carte</li>
        <li>Le Cellier</li>
        <li>Histoire</li>
        <li>Banquets Privés</li>
        <li>Réservations</li>
      </ul>
    </div>
  </div>
  <div class="footer-fleur">{FLEUR_DE_LIS_INLINE}</div>
  <div class="footer-bottom">
    <span class="star">✦</span>
    Maison de la Verrière · Anno Domini MMXXIV · Cuisine d'après les rouleaux de Reims et le Viandier de Taillevent
    <span class="star">✦</span>
  </div>
</footer>
"""


def page(title, body_html, active="page-1.html"):
    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title} — Maison de la Verrière</title>
<link rel="stylesheet" href="styles.css">
</head>
<body>
{header(active)}
{body_html}
{footer()}
</body>
</html>
"""
